CREATE TABLE evaluaciones_actividad_fisica (id BIGSERIAL PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES clientes(id),fecha_evaluacion DATE NOT NULL,instrumento_codigo VARCHAR(100) NOT NULL,instrumento_version VARCHAR(60) NOT NULL,nivel_resultado VARCHAR(100) NOT NULL,valor_resultado NUMERIC(14,4),fuente_referencia VARCHAR(300) NOT NULL,validada BOOLEAN NOT NULL,vigencia_desde DATE,vigencia_hasta DATE);
CREATE INDEX ix_evaluaciones_actividad_cliente ON evaluaciones_actividad_fisica(cliente_id,fecha_evaluacion DESC);
CREATE TABLE mapeos_categoria_actividad (id BIGSERIAL PRIMARY KEY,instrumento_codigo VARCHAR(100) NOT NULL,instrumento_version VARCHAR(60) NOT NULL,resultado_origen VARCHAR(100) NOT NULL,categoria_destino VARCHAR(100) NOT NULL,fuente_referencia VARCHAR(300) NOT NULL,version_referencia VARCHAR(100) NOT NULL,validada BOOLEAN NOT NULL,vigencia_desde DATE,vigencia_hasta DATE);
